    getSvgFromGameType: function(e) {
        let t = Jh.typeToDefSafe(e);
    
        if (!t)
            return ``;
        //M870 inventory renderingzz
        if (e === `m870`) {
            return `data:image/svg+xml;base64,`;
        }
        //scout elite to henry hlr for inventory render
        if (e === `scout_elite`) {
            return `data:image/svg+xml;base64,`;
        }
        switch (t.type) {
        case `gun`:
        case `melee`:
        case `throwable`:
        case `heal`:
        case `boost`:
        case `helmet`:
        case `chest`:
        case `scope`:
        case `backpack`:
        case `perk`:
        case `xp`:
            return `img/loot/${t.lootImg?.sprite.slice(0, -4)}.svg`;
    
        case `heal_effect`:
        case `boost_effect`:
            return `img/particles/${t.texture?.slice(0, -4)}.svg`;
    
        case `emote`:
            return `img/emotes/${t.texture.slice(0, -4)}.svg`;
    
        case `crosshair`:
            return `img/crosshairs/${t.texture.slice(0, -4)}.svg`;
    
        case `outfit`:
            return `img/loot/${t.lootImg.sprite.slice(0, -4)}.svg`;
    
        default:
            return ``
        }
    },
